import { NextResponse, type NextRequest } from "next/server";

const userManagementEnabled = process.env.NEXT_PUBLIC_USER_MANAGEMENT === "true";

async function middlewareHandler(request: NextRequest) {
    if (!userManagementEnabled) {
        return NextResponse.next();
    }

    // Dynamically import Clerk only when user management is enabled
    const { clerkMiddleware, createRouteMatcher } = await import("@clerk/nextjs/server");
    const isPublicRoute = createRouteMatcher(["/login(.*)", "/sso(.*)"]);

    return clerkMiddleware(async (auth, req) => {
        const { userId } = await auth();
        if (!userId && !isPublicRoute(req)) {
            return NextResponse.redirect(new URL('/login', req.url));
        }
    })(request, {} as any);
}

export default middlewareHandler;

export const config = {
    matcher: [
        // Skip Next.js internals and all static files, unless found in search params
        "/((?!_next|[^?]*\\.(?:html?|css|js(?!on)|jpe?g|webp|png|gif|svg|ttf|woff2?|ico|csv|docx?|xlsx?|zip|webmanifest)).*)",
        // Always run for API routes
        "/(api|trpc)(.*)",
    ],
};
